// Decodificar JWT del header Authorization
const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) {
  return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
}
const token = auth.slice(7);

// Decodificación simple del payload del JWT (sin verificación de firma — eso se hace en el siguiente nodo via función Postgres).
// Para producción real, validar firma vía Supabase Auth.
try {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('JWT malformed');
  const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));

  if (!payload.sub) throw new Error('No sub claim');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');

  return [{ json: {
    user_id:   payload.sub,
    tenant_id: payload.tenant_id || null,
    role:      payload.role      || 'architect',
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const profile = $input.first()?.json;
const sess = $('Decode JWT').first().json;
if (!profile || !profile.user_id) {
  return [{ json: {
    _error: 'PROFILE_NOT_FOUND',
    _status: 404,
    request_id: sess.request_id
  }}];
}
return [{ json: {
  data: {
    user_id:   profile.user_id,
    email:     profile.email,
    full_name: profile.full_name,
    role:      profile.role,
    tenant: {
      id:                profile.tenant_id,
      name:              profile.tenant_name,
      slug:              profile.tenant_slug,
      subscription_tier: profile.tenant_plan
    }
  },
  meta: {
    request_id: sess.request_id,
    timestamp:  new Date().toISOString()
  }
}}];
